import {localDate,decimal,generate,validateBackup} from './core.js';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal'),weekdays=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];let library=await fetch('exercises.json').then(r=>{if(!r.ok)throw Error('Biblioteca indisponível');return r.json()});const E=id=>library.find(e=>e.id===id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const db=await new Promise((resolve,reject)=>{let r=indexedDB.open('treino-pessoal',1);r.onupgradeneeded=()=>r.result.createObjectStore('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});const read=()=>new Promise((res,rej)=>{let r=db.transaction('state').objectStore('state').get('data');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});let state=await read()||{version:1,profile:null,plans:[],sessions:{},currentPlan:null};let writeChain=Promise.resolve();function save(){let snapshot=structuredClone(state);writeChain=writeChain.then(()=>new Promise((res,rej)=>{let t=db.transaction('state','readwrite');t.objectStore('state').put(snapshot,'data');t.oncomplete=res;t.onerror=()=>rej(t.error)})).catch(e=>{toast('Falha ao salvar. Exporte um backup antes de fechar.');console.error(e)});return writeChain}let tab='treino',selected=sessionStorage.getItem('selected-date')||Object.values(state.sessions).find(s=>s.status==='andamento'&&s.planId===state.currentPlan)?.date||localDate(),offset=0,scrolls={},timer=null,deadline=0;const plan=()=>state.plans.find(p=>p.id===state.currentPlan);const key=()=>plan().id+':'+selected;const record=()=>state.sessions[key()];function ensure(){if(!record()){let t=plan().dates[selected];if(!t)return null;state.sessions[key()]={id:key(),planId:plan().id,date:selected,name:t.name,status:'pendente',exercises:structuredClone(t.exercises).map(e=>({...e,done:false,load:null,loads:[],body:false}))}}return record()}const items=()=>record()?.exercises||plan()?.dates[selected]?.exercises||[];const previous=id=>Object.values(state.sessions).filter(s=>s.date<selected&&s.exercises.some(e=>e.exerciseId===id&&e.load!==null)).sort((a,b)=>b.date.localeCompare(a.date)).flatMap(s=>s.exercises.filter(e=>e.exerciseId===id&&e.load!==null))[0];function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.id);toast.id=setTimeout(()=>$('#toast').style.display='none',3500)}function show(html){modal.innerHTML=html;modal.showModal();modal.querySelector('[data-close]')?.addEventListener('click',()=>modal.close())}modal.addEventListener('close',()=>{modal.querySelectorAll('video').forEach(v=>v.pause());modal.innerHTML='';observeVideos()});function confirmAction(message,fn){show(`<h2>Confirmar alteração</h2><p>${esc(message)}</p><div class="actions"><button data-close>Cancelar</button><button class="primary" id="confirm">Confirmar</button></div>`);$('#confirm').onclick=async()=>{modal.close();await fn()}}
function render(){sessionStorage.setItem('selected-date',selected);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));if(!state.profile){onboarding();return}if(tab==='treino')workout();if(tab==='historico')history();if(tab==='ajustes')settings();observeVideos()}
function profileForm(edit=false){let p=state.profile||{},equipment=['máquinas','polia','halteres','barra','barra fixa'];return `<form id="profileform"><label>Objetivo<select name="goal" required><option value="">Selecione</option>${['hipertrofia','força','condicionamento'].map(v=>`<option ${p.goal===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Experiência<select name="level" required><option value="">Selecione</option>${['iniciante','intermediário','avançado'].map(v=>`<option ${p.level===v?'selected':''}>${v}</option>`).join('')}</select></label><div class="split"><label>Dias por semana<select name="frequency" required><option value="">Selecione</option>${[2,3,4,5,6].map(n=>`<option ${+p.frequency===n?'selected':''}>${n}</option>`).join('')}</select></label><label>Minutos por sessão<select name="minutes" required><option value="">Selecione</option>${[30,45,60,75].map(n=>`<option ${+p.minutes===n?'selected':''}>${n}</option>`).join('')}</select></label></div><fieldset><legend>Dias disponíveis</legend><div class="choices">${[1,2,3,4,5,6,0].map(d=>`<label><input name="days" type="checkbox" value="${d}" ${p.days?.includes(d)?'checked':''}>${weekdays[d]}</label>`).join('')}</div></fieldset><fieldset><legend>Equipamentos disponíveis</legend><div class="choices">${equipment.map(e=>`<label><input name="equipment" type="checkbox" value="${e}" ${p.equipment?.includes(e)?'checked':''}>${e}</label>`).join('')}</div></fieldset><label>Restrições ou limitações<textarea name="restrictions" required maxlength="1000" placeholder="Informe as limitações ou escreva “nenhuma”.">${esc(p.restrictions||'')}</textarea></label><p class="note">O plano é uma sugestão e pode ser revisado por um profissional. Restrições são registradas como observações, sem adaptação clínica automática.</p><p class="note">Biblioteca de academia: não cobre treino apenas com peso corporal. Sessões próximas podem exigir ajuste de dias para recuperação.</p><button class="primary full">${edit?'Salvar perfil':'Gerar meu plano'}</button><p id="formerror" role="alert" class="danger"></p></form>`}
function bindProfile(edit=false){$('#profileform').onsubmit=async ev=>{ev.preventDefault();let f=new FormData(ev.target),p=Object.fromEntries(f);p.days=f.getAll('days').map(Number);p.equipment=f.getAll('equipment');if(p.days.length!==+p.frequency){$('#formerror').textContent='Selecione exatamente '+p.frequency+' dias.';return}if(!p.equipment.length){$('#formerror').textContent='Selecione os equipamentos disponíveis.';return}try{if(!edit){let n=generate(p,library,localDate().slice(0,7));state.plans.push(n);state.currentPlan=n.id;selected=Object.keys(n.dates).find(d=>d>=localDate())||Object.keys(n.dates)[0]}state.profile=p;await save();if(edit)modal.close();render();toast(edit?'Perfil salvo. O plano atual foi preservado.':'Plano mensal criado')}catch(e){$('#formerror').textContent=e.message}}}
function onboarding(){app.innerHTML=`<div class="intro"><span class="eyebrow">Seu espaço de treino</span><h1>Vamos montar<br>seu primeiro mês.</h1><p class="muted">Um perfil rápido para organizar suas sessões. As cargas começam em branco.</p></div><div class="panel">${profileForm()}</div>`;bindProfile()}
function workout(){let p=plan();if(!p){app.innerHTML='<h1>Seu treino</h1><p>Gere um plano nos ajustes.</p>';return}let d=new Date(selected+'T12:00:00'),start=new Date(d);start.setDate(d.getDate()-((d.getDay()+6)%7));let dates=Array.from({length:7},(_,i)=>{let x=new Date(start);x.setDate(x.getDate()+i);return localDate(x)});let list=items(),r=record(),done=list.filter(e=>e.done).length;app.innerHTML=`<span class="eyebrow">Plano mensal</span><div class="row"><h1>${new Date(p.month+'-02T12:00').toLocaleDateString('pt-BR',{month:'long'})} <span class="muted" style="font-weight:400;font-size:19px">${p.month.slice(0,4)}</span></h1><button class="ghost" id="today">Hoje</button></div><small>${esc(p.split)} · ${p.profile.frequency} dias por semana</small><div class="weeknav"><button id="prevweek" aria-label="Semana anterior">‹</button><small>${dates[0].slice(8)} ${new Date(dates[0]+'T12:00').toLocaleDateString('pt-BR',{month:'short'})} — ${dates[6].slice(8)} ${new Date(dates[6]+'T12:00').toLocaleDateString('pt-BR',{month:'short'})}</small><button id="nextweek" aria-label="Próxima semana">›</button></div><div class="days">${dates.map(date=>`<button class="day ${date===selected?'active':''}" data-date="${date}" aria-pressed="${date===selected}"><span>${weekdays[new Date(date+'T12:00').getDay()]}</span><b>${date.slice(8)}</b>${p.dates[date]?'<i></i>':'<i style="opacity:0"></i>'}</button>`).join('')}</div><div class="session"><span class="eyebrow">${selected===localDate()?'Hoje':d.toLocaleDateString('pt-BR',{day:'numeric',month:'long'})}</span><div class="row"><h2>${esc(r?.name||p.dates[selected]?.name||'Descanso')}</h2><small>${r?.status==='concluído'?'✓ Concluído':r?.status==='parcial'?'Parcial':r?.status==='andamento'?'Em andamento':''}</small></div>${list.length?`<div class="row"><small>${done} de ${list.length} exercícios</small><small>${p.profile.minutes} min previstos</small></div><div class="progress"><div style="width:${done/list.length*100}%"></div></div><button id="sessionaction" class="primary full">${r?.status==='andamento'?'Finalizar treino':r?.status==='concluído'||r?.status==='parcial'?'Retomar treino':'Iniciar treino'}</button>`:'<p class="muted">Nenhuma sessão planejada para esta data.</p>'}</div>${list.length?`<div class="row"><span class="eyebrow">Exercícios</span><button class="ghost" id="restbutton" style="font-size:12px">◷ Descanso</button></div>`:''}${list.map((x,i)=>exerciseCard(x,i)).join('')}`;
$('#today').onclick=()=>{selected=localDate();render()};$('#prevweek').onclick=()=>moveWeek(-7);$('#nextweek').onclick=()=>moveWeek(7);app.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{selected=b.dataset.date;render()});$('#sessionaction')?.addEventListener('click',()=>{let s=ensure();if(s.status==='andamento'){let pending=s.exercises.some(e=>!e.done);confirmAction(pending?'Há exercícios pendentes. Salvar como treino parcial?':'Finalizar e salvar este treino?',()=>{s.status=pending?'parcial':'concluído';s.finished=Date.now();save();render()})}else{s.status='andamento';s.started=s.started||Date.now();save();render()}});$('#restbutton')?.addEventListener('click',()=>rest(75));bindExercises()}
function moveWeek(n){let d=new Date(selected+'T12:00');d.setDate(d.getDate()+n);selected=localDate(d);render()}
function exerciseCard(x,i){let e=E(x.exerciseId),old=previous(e.id);return `<article class="exercise ${x.done?'done':''}"><div class="exercisehead"><button class="thumb" data-demo="${e.id}" aria-label="Ver demonstração: ${esc(e.name)}"><video muted loop playsinline preload="none" poster="${e.poster}" data-src="${e.media}"></video><span class="playbadge">▶</span></button><div class="exname"><h3>${esc(e.name)}</h3><small>${x.sets} séries × ${esc(x.reps)} · ${x.rest}s descanso</small></div><button class="check ${x.done?'checked':''}" data-check="${i}" aria-label="${x.done?'Desmarcar':'Concluir'} ${esc(e.name)}" aria-pressed="${!!x.done}">${x.done?'✓':'○'}</button></div><div class="loadrow"><div class="loadbox"><input inputmode="decimal" aria-label="Carga ${esc(e.name)}" data-load="${i}" value="${x.load??''}" placeholder="—"><small>kg${e.equipment==='halteres'?'/ halter':''}</small></div><div class="last">${old?`Anterior: ${old.load} kg <button data-reuse="${i}">Usar</button>`:'Sem carga anterior'}</div></div><details data-detail="${i}"><summary>Séries e detalhes</summary>${x.warmup?'<p class="note">Aquecimento: 1–2 séries leves antes das séries principais. Não contam no total acima.</p>':''}<label><input type="checkbox" data-body="${i}" ${x.body?'checked':''}> Registrar peso corporal</label>${Array.from({length:x.sets},(_,n)=>`<div class="series"><small>Série ${n+1}</small><input inputmode="decimal" data-series="${i}:${n}" value="${x.loads?.[n]??''}" placeholder="—" aria-label="Carga da série ${n+1}"><small>kg</small></div>`).join('')}<div class="actions"><button data-rest="${x.rest}">Descanso ${x.rest}s</button><button data-replace="${i}">Substituir</button></div></details></article>`}
function bindExercises(){app.querySelectorAll('[data-check]').forEach(b=>b.onclick=()=>{let y=scrollY,s=ensure();s.exercises[b.dataset.check].done=!s.exercises[b.dataset.check].done;save();render();window.scrollTo(0,y)});app.querySelectorAll('[data-load],[data-series]').forEach(input=>input.oninput=()=>{try{let value=decimal(input.value),s=ensure();if(input.dataset.load!==undefined)s.exercises[input.dataset.load].load=value;else{let [i,n]=input.dataset.series.split(':');s.exercises[i].loads[n]=value}input.setCustomValidity('');save()}catch(e){input.setCustomValidity(e.message);toast(e.message)}});app.querySelectorAll('[data-body]').forEach(b=>b.onchange=()=>{ensure().exercises[b.dataset.body].body=b.checked;save()});app.querySelectorAll('[data-reuse]').forEach(b=>b.onclick=()=>{let i=+b.dataset.reuse,s=ensure();s.exercises[i].load=previous(s.exercises[i].exerciseId).load;save();let input=app.querySelector(`[data-load="${i}"]`);input.value=s.exercises[i].load;toast('Carga anterior registrada')});app.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>demo(b.dataset.demo));app.querySelectorAll('[data-rest]').forEach(b=>b.onclick=()=>rest(+b.dataset.rest));app.querySelectorAll('[data-replace]').forEach(b=>b.onclick=()=>replace(+b.dataset.replace,false))}
let observer;function observeVideos(){observer?.disconnect();observer=new IntersectionObserver(entries=>entries.forEach(({target:v,isIntersecting})=>{if(isIntersecting&&!matchMedia('(prefers-reduced-motion: reduce)').matches){if(!v.src)v.src=v.dataset.src;v.play().catch(()=>{})}else v.pause()}),{threshold:.3});app.querySelectorAll('video').forEach(v=>observer.observe(v))}document.addEventListener('visibilitychange',()=>{if(document.hidden)document.querySelectorAll('video').forEach(v=>v.pause());else observeVideos()});
function demo(id){document.querySelectorAll('video').forEach(v=>v.pause());let e=E(id);show(`<div class="row"><h2>${esc(e.name)}</h2><button data-close aria-label="Fechar">✕</button></div><video id="demovideo" src="${e.media}" poster="${e.poster}" controls loop playsinline muted ${matchMedia('(prefers-reduced-motion: reduce)').matches?'':'autoplay'}></video><ul>${e.tips.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><small>Vídeo: ${esc(e.author)} · <a href="${e.licenseURL}" target="_blank" rel="noopener">${e.license}</a></small>`)}
function rest(seconds){if(!deadline)deadline=Date.now()+seconds*1000;show(`<div class="row"><h2>Descanso</h2><button data-close>Fechar</button></div><p class="bigzero" id="countdown"></p><div class="actions"><button id="plus">+ 15s</button><button id="stop">Encerrar</button></div>`);const tick=()=>{let n=Math.max(0,Math.ceil((deadline-Date.now())/1000));if($('#countdown'))$('#countdown').textContent=`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;if(n===0){clearInterval(timer);deadline=0;toast('Descanso concluído')}};clearInterval(timer);tick();timer=setInterval(tick,500);$('#plus').onclick=()=>{deadline=(deadline||Date.now())+15000;tick()};$('#stop').onclick=()=>{clearInterval(timer);deadline=0;modal.close()}}
function replace(i,edit,date=selected){let list=edit?plan().dates[date].exercises:items(),e=E(list[i].exerciseId),alts=library.filter(a=>e.alternatives.includes(a.id)&&state.profile.equipment.includes(a.equipment)&&a.level<=(state.profile.level==='iniciante'?1:2));show(`<div class="row"><h2>Substituir exercício</h2><button data-close>Fechar</button></div><p class="note">Mesmo grupo e padrão de movimento. ${edit?'Altera esta data do plano.':'Apenas nesta sessão.'}</p>${alts.length?alts.map(a=>`<button class="full" style="margin:6px 0" data-alt="${a.id}">${esc(a.name)} <small>· ${a.equipment}</small></button>`).join(''):'<p>Não há alternativa compatível com seus equipamentos nesta seleção.</p>'}`);modal.querySelectorAll('[data-alt]').forEach(b=>b.onclick=()=>{let target=edit?plan().dates[date].exercises:ensure().exercises;if(!edit&&(target[i].done||target[i].load!==null||target[i].loads.some(v=>v!==null)))return confirmAction('Este exercício já possui registros. A substituição desta sessão limpará esses campos. Continuar?',()=>apply());apply();function apply(){target[i]={...target[i],exerciseId:b.dataset.alt,done:false,load:null,loads:[],body:false};save();modal.close();render()}})}
function history(){let sessions=Object.values(state.sessions).filter(s=>s.status==='concluído'||s.status==='parcial').sort((a,b)=>b.date.localeCompare(a.date));app.innerHTML=`<span class="eyebrow">Seus registros</span><h1>Histórico</h1><p class="muted">Sessões salvas e cargas utilizadas.</p><div class="split"><div class="panel"><div class="bigzero">${sessions.length}</div><small>sessões realizadas</small></div><div class="panel"><div class="bigzero">${sessions.reduce((n,s)=>n+s.exercises.filter(e=>e.done).length,0)}</div><small>exercícios concluídos</small></div></div><div class="panel"><h3>Evolução de carga</h3><label>Exercício<select id="evolution"><option value="">Selecione</option>${library.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></label><div id="evolutionlist"><small>As cargas aparecem após seus primeiros registros.</small></div></div><h2>Sessões</h2>${sessions.length?sessions.map(s=>`<details class="historyitem"><summary>${new Date(s.date+'T12:00').toLocaleDateString('pt-BR')} · ${esc(s.name)} · ${s.status}</summary>${s.exercises.map(e=>`<p><b>${e.done?'✓':'○'} ${esc(E(e.exerciseId).name)}</b><br><small>${e.sets} × ${esc(e.reps)} · ${e.body?'Peso corporal':e.load===null?'Sem carga registrada':e.load+' kg'}${e.loads.length?' · séries: '+e.loads.map(n=>n===null?'—':n+' kg').join(' / '):''}</small></p>`).join('')}</details>`).join(''):'<p class="muted empty">Seus treinos finalizados aparecerão aqui.</p>'}`;$('#evolution').onchange=ev=>{$('#evolutionlist').innerHTML=sessions.slice().reverse().flatMap(s=>s.exercises.filter(e=>e.exerciseId===ev.target.value).map(e=>`<div class="row historyitem"><small>${s.date.split('-').reverse().join('/')}</small><strong>${e.load===null?'—':e.load+' kg'}</strong></div>`)).join('')||'<small>Nenhum registro para este exercício.</small>'}}
function settings(){app.innerHTML=`<span class="eyebrow">Preferências</span><h1>Ajustes</h1><div class="panel"><div class="row"><h3>Seu perfil</h3><button id="editprofile">Editar</button></div><p class="muted">${esc(state.profile.goal)} · ${esc(state.profile.level)}<br>${state.profile.frequency} dias · ${state.profile.minutes} min</p>${state.profile.restrictions.toLowerCase()!=='nenhuma'?`<small>Observações: ${esc(state.profile.restrictions)}. Não são aplicadas adaptações clínicas automáticas.</small>`:''}</div><div class="panel"><h3>Planos mensais</h3><select id="planselect" class="monthselect">${state.plans.map(p=>`<option value="${p.id}" ${p.id===state.currentPlan?'selected':''}>${p.month.split('-').reverse().join('/')} · ${new Date(p.created).toLocaleDateString('pt-BR')}</option>`).join('')}</select><div class="actions"><button id="editplan">Editar plano</button><button id="newplan">Novo plano</button></div><small>Planos anteriores e registros são preservados.</small></div><div class="panel"><h3>Conteúdo offline</h3><p class="note">Baixe apenas os vídeos e miniaturas do plano selecionado. O navegador pode remover arquivos quando faltar espaço.</p><button id="download" class="full">Verificar e baixar mídias</button><p id="downloadstatus" role="status" class="note"></p></div><div class="panel"><h3>Backup</h3><p class="note">Dados apenas neste navegador e dispositivo, sem sincronização automática. Exporte periodicamente.</p><button class="full" id="export">Exportar backup JSON</button><label>Importar backup<input type="file" id="import" accept="application/json,.json"></label></div><details class="panel"><summary>Instalar e informações</summary><p class="note">iPhone: abra no Safari, toque em Compartilhar e em Adicionar à Tela de Início. Android: abra no Chrome e escolha Instalar aplicativo no menu.</p><p class="note">24 exercícios com vídeos locais. O catálogo não contempla todos os equipamentos e movimentos. As regras não usam IA e não aumentam cargas.</p><a href="CREDITOS.md">Fontes e licenças</a><p><button id="erase" class="danger full">Excluir todos os dados</button></p></details>`;$('#editprofile').onclick=()=>{show(`<div class="row"><h2>Seu perfil</h2><button data-close>Fechar</button></div>${profileForm(true)}`);bindProfile(true)};$('#planselect').onchange=async e=>{state.currentPlan=e.target.value;await save();selected=Object.keys(plan().dates)[0];toast('Plano selecionado')};$('#newplan').onclick=()=>{show('<h2>Novo plano mensal</h2><label>Mês<input id="newmonth" type="month" value="'+localDate().slice(0,7)+'"></label><p class="note">O plano atual e todas as sessões serão arquivados e preservados.</p><div class="actions"><button data-close>Cancelar</button><button id="generate" class="primary">Gerar novo plano</button></div><p id="generror" class="danger"></p>');$('#generate').onclick=()=>{try{let month=$('#newmonth').value;if(!month)throw Error('Selecione o mês.');let p=generate(state.profile,library,month);confirmAction('Criar e selecionar este novo plano, preservando os anteriores?',()=>{state.plans.push(p);state.currentPlan=p.id;selected=Object.keys(p.dates)[0];save();render()})}catch(e){$('#generror').textContent=e.message}}};$('#editplan').onclick=()=>editPlan();$('#download').onclick=downloadPlan;$('#export').onclick=async()=>{await writeChain;let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='treino-backup-'+localDate()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)};$('#import').onchange=async e=>{try{let file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw Error('Arquivo maior que 10 MB.');let data=validateBackup(JSON.parse(await file.text()),library);confirmAction('Substituir os dados deste dispositivo pelo backup selecionado? Exporte o atual antes, se necessário.',async()=>{state=structuredClone(data);await save();render();toast('Backup importado')})}catch(e){toast('Não foi possível importar: '+e.message)}};$('#erase').onclick=()=>confirmAction('Excluir perfil, planos e todos os registros deste navegador? Esta ação não pode ser desfeita.',async()=>{state={version:1,profile:null,plans:[],sessions:{},currentPlan:null};await save();tab='treino';render()})}
function editPlan(date){let dates=Object.keys(plan().dates);date=date||dates[0];let t=plan().dates[date];show(`<div class="row"><h2>Editar plano</h2><button data-close>Fechar</button></div><p class="note">Altera somente a definição desta data. Sessões já registradas mantêm sua cópia original.</p><label>Sessão<select id="editdate">${dates.map(d=>`<option ${date===d?'selected':''} value="${d}">${d.split('-').reverse().join('/')} · ${esc(plan().dates[d].name)}</option>`).join('')}</select></label>${t.exercises.map((x,i)=>`<div class="historyitem"><h3>${esc(E(x.exerciseId).name)}</h3><div class="editgrid"><label>Séries<input type="number" min="1" max="10" value="${x.sets}" data-edit="${i}:sets"></label><label>Repetições<input maxlength="30" value="${esc(x.reps)}" data-edit="${i}:reps"></label><label>Descanso (s)<input type="number" min="0" max="600" value="${x.rest}" data-edit="${i}:rest"></label></div><div class="actions"><button data-up="${i}" ${i===0?'disabled':''}>↑ Ordem</button><button data-swap="${i}">Substituir</button></div></div>`).join('')}<button class="full primary" id="saveedit">Salvar alterações</button>`);$('#editdate').onchange=e=>{modal.close();editPlan(e.target.value)};let draft=structuredClone(t.exercises);modal.querySelectorAll('[data-edit]').forEach(input=>input.oninput=()=>{let [i,k]=input.dataset.edit.split(':');draft[i][k]=k==='reps'?input.value:+input.value});$('#saveedit').onclick=()=>{if(draft.some(e=>!Number.isInteger(e.sets)||e.sets<1||e.sets>10||!e.reps.trim()||!Number.isFinite(e.rest)||e.rest<0||e.rest>600))return toast('Verifique séries (1–10), repetições e descanso (0–600s).');plan().dates[date].exercises=draft;save();modal.close();toast('Plano salvo; histórico preservado')};modal.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>{let i=+b.dataset.up;[t.exercises[i-1],t.exercises[i]]=[t.exercises[i],t.exercises[i-1]];save();modal.close();editPlan(date)});modal.querySelectorAll('[data-swap]').forEach(b=>b.onclick=()=>{modal.close();replace(+b.dataset.swap,true,date)})}
async function downloadPlan(){let status=$('#downloadstatus'),button=$('#download');if(!('serviceWorker'in navigator)||!('caches'in window)){status.textContent='Offline indisponível neste navegador.';return}button.disabled=true;try{await Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(Error('Service worker indisponível')),10000))]);for(let file of ['index.html','app.js','core.js','style.css','exercises.json'])if(!await caches.match(new URL(file,location.href).href))throw Error('Aplicativo ainda não armazenado');let cache=await caches.open('treino-media-v1'),ids=[...new Set([...Object.values(plan().dates).flatMap(t=>t.exercises.map(e=>e.exerciseId)),...Object.values(state.sessions).filter(s=>s.planId===plan().id).flatMap(s=>s.exercises.map(e=>e.exerciseId))])],urls=ids.flatMap(id=>[E(id).media,E(id).poster]),failed=[];for(let [i,url] of urls.entries()){status.textContent=`Verificando ${i+1} de ${urls.length} arquivos…`;try{let abs=new URL(url,location.href).href,r=await cache.match(abs);if(!r){r=await fetch(abs);if(!r.ok)throw Error();await cache.put(abs,r.clone())}if(!(await cache.match(abs)))throw Error()}catch{failed.push(url)}}status.textContent=failed.length?`${failed.length} arquivos falharam. Toque novamente para tentar.`:'Mídias verificadas. Plano pronto para uso offline neste navegador.';navigator.storage?.persist?.()}catch{status.textContent='Não foi possível preparar o conteúdo offline. Tente novamente.'}finally{button.disabled=false}}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{scrolls[tab]=scrollY;tab=b.dataset.tab;render();window.scrollTo(0,scrolls[tab]||0)});window.addEventListener('online',()=>$('#connection').textContent='Pessoal · Local');window.addEventListener('offline',()=>$('#connection').textContent='Sem conexão');if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>toast('Recurso offline indisponível'));render();
